const app = document.getElementById('app');
const searchInput = document.getElementById('globalSearch');
const state = { user:null, categories:[], posts:[], saved:[], trade:'All trades', sort:'helpful', authMode:'login', currentPost:null, kpis:{published:0,users:0,comments:0,ratings:0,engagement:0,views:0,contributors:0,contributionRate:0} };
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = name => String(name||'?').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function go(route){location.hash=route}
function route(){const bits=decodeURIComponent(location.hash.replace(/^#\/?/, '')).split('/');return {page:bits[0]||'feed',id:bits[1]||'',view:bits[1]||'members'}}
async function api(path,options={}){const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data}
async function refresh(){const data=await api('/bootstrap');state.user=data.user;state.categories=data.categories;state.posts=data.posts;state.saved=data.saved;state.kpis=data.kpis||state.kpis;syncHeader()}
function syncHeader(){document.getElementById('userLabel').textContent=state.user?state.user.name:'Sign in';document.getElementById('userBadge').textContent=state.user?initials(state.user.name):'?';document.querySelector('.user-link').href=state.user?'#/dashboard':'#/login'}
function head(kicker,title,sub='',actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1 class="page-title">${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>`}
function postCard(p){const saved=state.saved.includes(p.id);return `<article class="card"><div class="post-top"><a class="tag" href="#/category/${encodeURIComponent(p.trade)}">${esc(p.trade)} · ${esc(p.kind)}</a>${p.videoUrl?'<span class="video-available">▶ VIDEO</span>':''}<button class="bookmark ${saved?'on':''}" data-save="${esc(p.id)}" aria-label="${saved?'Remove bookmark':'Bookmark guide'}">${saved?'▣':'♧'}</button></div><h2 class="post-title"><a href="#/post/${encodeURIComponent(p.id)}">${esc(p.title)}</a></h2><p class="post-desc">${esc(p.summary)}</p><div class="guide-rating-summary" aria-label="${p.ratingCount?`${p.ratingAverage} out of 5 stars from ${p.ratingCount} ratings`:'Not rated yet'}">★ ${p.ratingCount?`${Number(p.ratingAverage).toFixed(1)} · ${p.ratingCount} ${p.ratingCount===1?'rating':'ratings'}`:'Not rated yet'}</div><div class="post-meta"><div class="author"><span class="portrait">${esc(p.initials||initials(p.author))}</span><div><b>${esc(p.author)}</b><small>${esc(p.role)} · ${esc(p.date)} · ${p.minutes} min</small></div></div><div class="stats"><button data-helpful="${esc(p.id)}" title="Mark helpful">♡ ${p.helpful||0}</button><span>▤ ${p.commentCount??p.comments?.length??0}</span><span>◉ ${p.views||0}</span></div></div></article>`}
async function toggleSaved(id){try{const r=await api(`/bookmarks/${encodeURIComponent(id)}`,{method:'POST',body:'{}'});state.saved=r.saved?[...state.saved,id]:state.saved.filter(x=>x!==id);toast(r.saved?'Saved to your dashboard':'Removed from saved guides');if(state.currentPost?.id===id&&route().page==='post'){renderPostWithoutFetch(state.currentPost)}else render()}catch(e){toast(e.message);if(!state.user)go('#/login')}}
async function markHelpful(id){try{const r=await api(`/posts/${encodeURIComponent(id)}/helpful`,{method:'POST',body:'{}'});const p=state.posts.find(x=>x.id===id);if(p)p.helpful=r.helpful;if(state.currentPost?.id===id&&route().page==='post'){state.currentPost.helpful=r.helpful;renderPostWithoutFetch(state.currentPost)}else render();toast(r.marked?'Marked helpful':'Helpful vote removed')}catch(e){toast(e.message);if(!state.user)go('#/login')}}
function bindCards(){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggleSaved(b.dataset.save));document.querySelectorAll('[data-helpful]').forEach(b=>b.onclick=()=>markHelpful(b.dataset.helpful))}
function matchingPosts(list){const q=searchInput.value.trim().toLowerCase();return list.filter(p=>(state.trade==='All trades'||p.trade===state.trade)&&(!q||`${p.title} ${p.summary} ${p.trade} ${p.body}`.toLowerCase().includes(q))).sort((a,b)=>state.sort==='helpful'?(b.helpful||0)-(a.helpful||0):String(b.date).localeCompare(String(a.date)))}
function renderFeed(){const list=matchingPosts(state.posts);app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A PRACTICAL KNOWLEDGE EXCHANGE</div><h1>Trade wisdom.<br>Passed forward.</h1><p>Field-tested fixes, workshop notes, and the little things you only learn by doing the work.</p><button class="btn btn-primary" id="heroWrite">＋ Add to the journal</button></div></section><div class="feed-head"><div><h2>The working knowledge</h2><p>Useful notes, shared by people who do the work.</p></div><button class="btn" id="sortToggle">↕ &nbsp;${state.sort==='helpful'?'Most helpful':'Latest'}</button></div><div class="layout"><section><div class="filters" id="feedFilters">${['All trades',...state.categories.map(c=>c.name)].map(t=>`<button class="chip ${state.trade===t?'active':''}" data-filter="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="feed" id="postFeed">${list.length?list.map(postCard).join(''):'<div class="card empty">No notes match your search yet. Try another trade or keyword.</div>'}</div></section><aside class="side"><div class="side-card"><h3>Browse a trade</h3>${state.categories.map(c=>`<a class="trade-row" href="#/category/${encodeURIComponent(c.name)}"><span>✳ &nbsp;${esc(c.name)}</span><span class="count">${state.posts.filter(p=>p.trade===c.name).length.toString().padStart(2,'0')}</span></a>`).join('')}</div><div class="side-card"><h3>Popular this week <span style="color:var(--orange)">↗</span></h3>${[...state.posts].sort((a,b)=>(b.views||0)-(a.views||0)).slice(0,3).map((p,i)=>`<a class="trend-item" href="#/post/${encodeURIComponent(p.id)}"><span class="trend-rank">0${i+1}</span><span><b>${esc(p.title)}</b><small>${esc(p.trade)} · ${p.views} reads</small></span></a>`).join('')}</div><div class="side-card note-card"><div class="eyebrow">A NOTE FROM THE FIELD</div><h3>Every trade has a trick worth passing on.</h3><p>Help the next person get it right the first time.</p><button class="btn btn-dark" id="sideWrite">Write a guide →</button></div></aside></div>`;
 document.getElementById('heroWrite').onclick=()=>go('#/create');document.getElementById('sideWrite').onclick=()=>go('#/create');document.getElementById('sortToggle').onclick=()=>{state.sort=state.sort==='helpful'?'latest':'helpful';render()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.trade=b.dataset.filter;renderFeed()});bindCards()}
function renderCategory(name){const cat=state.categories.find(c=>c.name.toLowerCase()===name.toLowerCase());const list=state.posts.filter(p=>p.trade.toLowerCase()===name.toLowerCase()).sort((a,b)=>(b.helpful||0)-(a.helpful||0));app.innerHTML=`<section class="page">${head('TRADE CATEGORY',esc(name),esc(cat?.description||'Practical how-to notes from skilled trade professionals.'),`<a class="btn btn-primary" href="#/create">＋ Share a guide</a>`)}<div class="filters">${state.categories.map(c=>`<a class="chip ${c.name===name?'active':''}" href="#/category/${encodeURIComponent(c.name)}">${esc(c.name)}</a>`).join('')}</div><div class="feed">${list.length?list.map(postCard).join(''):'<div class="card empty">No published notes in this category yet. Share the first guide.</div>'}</div></section>`;bindCards()}
async function renderPost(id){app.innerHTML='<div class="card empty">Opening the field note…</div>';try{const {post:p}=await api(`/posts/${encodeURIComponent(id)}`);state.currentPost=p;const saved=state.saved.includes(id);app.innerHTML=`<section class="page"><div style="margin-bottom:14px"><a class="tag" href="#/category/${encodeURIComponent(p.trade)}">← ${esc(p.trade)} · ${esc(p.kind)}</a></div><article class="detail-hero"><div class="eyebrow">FIELD NOTE · ${esc(p.date)}</div><h1>${esc(p.title)}</h1><p class="detail-summary">${esc(p.summary)}</p><div class="post-meta"><div class="author"><span class="portrait">${esc(p.initials||initials(p.author))}</span><div><b>${esc(p.author)}</b><small>${esc(p.role)} · ${p.minutes} min read · ${p.views} reads</small></div></div><div class="stats"><button class="btn btn-sm" id="detailHelpful">♡ Helpful · ${p.helpful||0}</button><button class="btn btn-sm" id="detailSave">${saved?'▣ Saved':'♧ Save guide'}</button></div></div></article>${p.image?`<img class="detail-image" src="${esc(p.image)}" alt="Step-by-step trade guide image" onerror="this.hidden=true">`:''}<div class="split" style="margin-top:17px"><section class="form-card"><div class="article-body">${esc(p.body)}</div><div class="safety-note">Safety reminder: Follow workplace procedures, applicable local codes, PPE requirements, and manufacturer documentation. Consult a qualified supervisor if conditions differ from this guide.</div><h2 class="post-title" style="margin-top:23px">Community discussion (${p.comments.length})</h2><div>${p.comments.length?p.comments.map(c=>`<div class="comment"><b>${esc(c.name)}</b><div>${esc(c.text)}</div><small>${esc(c.date||'Community comment')}</small></div>`).join(''):'<p class="hint">No comments yet. Share a useful clarification or field note.</p>'}</div><form id="commentForm"><div class="field"><label for="commentText">Add a comment</label><textarea id="commentText" name="text" required maxlength="500" placeholder="Add a tip, clarification, or question…"></textarea></div><button class="btn btn-primary">Post comment</button></form></section><aside class="side"><div class="side-card"><div class="eyebrow">IN THIS TRADE</div><h3>Keep learning</h3><p class="hint">Explore more ${esc(p.trade)} notes from the community.</p><a class="btn" href="#/category/${encodeURIComponent(p.trade)}">Browse ${esc(p.trade)} guides →</a></div><div class="side-card"><h3>Share this knowledge</h3><p class="hint">Pass this field note along to a learner or colleague.</p></div></aside></div></section>`;
 document.getElementById('detailHelpful').onclick=()=>markHelpful(id);document.getElementById('detailSave').onclick=()=>toggleSaved(id);document.getElementById('commentForm').onsubmit=async e=>{e.preventDefault();try{const text=new FormData(e.target).get('text').trim();const result=await api(`/posts/${encodeURIComponent(id)}/comments`,{method:'POST',body:JSON.stringify({text})});state.currentPost=result.post;toast('Comment posted');renderPostWithoutFetch(result.post)}catch(err){toast(err.message);if(!state.user)go('#/login')}};
 }catch(e){app.innerHTML=`<section class="page">${head('FIELD NOTE','Guide unavailable',esc(e.message))}<a class="btn" href="#/feed">Back to the journal</a></section>`}}
function renderPostWithoutFetch(p){state.currentPost=p;const saved=state.saved.includes(p.id);app.innerHTML=`<section class="page"><div style="margin-bottom:14px"><a class="tag" href="#/category/${encodeURIComponent(p.trade)}">← ${esc(p.trade)} · ${esc(p.kind)}</a></div><article class="detail-hero"><div class="eyebrow">FIELD NOTE · ${esc(p.date)}</div><h1>${esc(p.title)}</h1><p class="detail-summary">${esc(p.summary)}</p><div class="post-meta"><div class="author"><span class="portrait">${esc(p.initials||initials(p.author))}</span><div><b>${esc(p.author)}</b><small>${esc(p.role)} · ${p.minutes} min read · ${p.views} reads</small></div></div><div class="stats"><button class="btn btn-sm" id="detailHelpful">♡ Helpful · ${p.helpful||0}</button><button class="btn btn-sm" id="detailSave">${saved?'▣ Saved':'♧ Save guide'}</button></div></div></article>${p.image?`<img class="detail-image" src="${esc(p.image)}" alt="Step-by-step trade guide image">`:''}<div class="split" style="margin-top:17px"><section class="form-card"><div class="article-body">${esc(p.body)}</div><div class="safety-note">Safety reminder: Follow workplace procedures, applicable local codes, PPE requirements, and manufacturer documentation.</div><h2 class="post-title" style="margin-top:23px">Community discussion (${p.comments.length})</h2><div>${p.comments.length?p.comments.map(c=>`<div class="comment"><b>${esc(c.name)}</b><div>${esc(c.text)}</div><small>${esc(c.date||'Community comment')}</small></div>`).join(''):'<p class="hint">No comments yet.</p>'}</div><form id="commentForm"><div class="field"><label for="commentText">Add a comment</label><textarea id="commentText" name="text" required maxlength="500" placeholder="Add a tip, clarification, or question…"></textarea></div><button class="btn btn-primary">Post comment</button></form></section><aside class="side"><div class="side-card"><div class="eyebrow">IN THIS TRADE</div><h3>Keep learning</h3><a class="btn" href="#/category/${encodeURIComponent(p.trade)}">Browse ${esc(p.trade)} guides →</a></div></aside></div></section>`;document.getElementById('detailHelpful').onclick=()=>markHelpful(p.id);document.getElementById('detailSave').onclick=()=>toggleSaved(p.id);document.getElementById('commentForm').onsubmit=async e=>{e.preventDefault();try{const result=await api(`/posts/${encodeURIComponent(p.id)}/comments`,{method:'POST',body:JSON.stringify({text:new FormData(e.target).get('text').trim()})});toast('Comment posted');renderPostWithoutFetch(result.post)}catch(err){toast(err.message);if(!state.user)go('#/login')}}}
function renderPostWithoutFetch(p){state.currentPost=p;const saved=state.saved.includes(p.id);app.innerHTML=`<section class="page"><div style="margin-bottom:14px"><a class="tag" href="#/category/${encodeURIComponent(p.trade)}">← ${esc(p.trade)} · ${esc(p.kind)}</a></div><article class="detail-hero"><div class="eyebrow">FIELD NOTE · ${esc(p.date)}</div><h1>${esc(p.title)}</h1><p class="detail-summary">${esc(p.summary)}</p><div class="post-meta"><div class="author"><span class="portrait">${esc(p.initials||initials(p.author))}</span><div><b>${esc(p.author)}</b><small>${esc(p.role)} · ${p.minutes} min read · ${p.views} reads</small></div></div><div class="stats"><button class="btn btn-sm" id="detailHelpful">♡ Helpful · ${p.helpful||0}</button><button class="btn btn-sm" id="detailSave">${saved?'▣ Saved':'♧ Save guide'}</button></div></div></article>${p.image?`<img class="detail-image" src="${esc(p.image)}" alt="Step-by-step trade guide image">`:''}<div class="split" style="margin-top:17px"><section class="form-card"><div class="article-body">${esc(p.body)}</div><div class="safety-note">Safety reminder: Follow workplace procedures, applicable local codes, PPE requirements, and manufacturer documentation.</div><h2 class="post-title" style="margin-top:23px">Community discussion (${p.comments.length})</h2><div>${p.comments.length?p.comments.map(c=>`<div class="comment"><b>${esc(c.name)}</b><div>${esc(c.text)}</div><small>${esc(c.date||'Community comment')}</small></div>`).join(''):'<p class="hint">No comments yet.</p>'}</div><form id="commentForm"><div class="field"><label for="commentText">Add a comment</label><textarea id="commentText" name="text" required maxlength="500" placeholder="Add a tip, clarification, or question…"></textarea></div><button class="btn btn-primary">Post comment</button></form></section><aside class="side"><div class="side-card"><div class="eyebrow">IN THIS TRADE</div><h3>Keep learning</h3><a class="btn" href="#/category/${encodeURIComponent(p.trade)}">Browse ${esc(p.trade)} guides →</a></div></aside></div></section>`;document.getElementById('detailHelpful').onclick=()=>markHelpful(p.id);document.getElementById('detailSave').onclick=()=>toggleSaved(p.id);document.getElementById('commentForm').onsubmit=async e=>{e.preventDefault();try{const result=await api(`/posts/${encodeURIComponent(p.id)}/comments`,{method:'POST',body:JSON.stringify({text:new FormData(e.target).get('text').trim()})});state.currentPost=result.post;toast('Comment posted');renderPostWithoutFetch(result.post)}catch(err){toast(err.message);if(!state.user)go('#/login')}}}
function renderFlow(){const flows=[{stamp:'PATH 01 · LEARNER',title:'User flow',role:'Professional / student',intro:'Find a practical answer, learn from an experienced trade professional, and carry that knowledge into your next task.',steps:[['Register / Login','Create a member account or sign in.','#/login'],['Create profile','Add your trade and experience so contributions have context.','#/dashboard'],['Browse trade categories','Choose a specialty and explore its field notes.','#/category/Electrical'],['Read tutorials or guides','Open a practical guide with its steps, notes, and video when available.','#/post/p106'],['Publish knowledge articles','Share a tested technique or a troubleshooting sequence.','#/create'],['Interact through comments','Ask a useful question or add a field-tested clarification.','#/post/p104']],cta:'Start learning',route:'#/feed'},{stamp:'PATH 02 · CONTRIBUTOR',title:'Knowledge contributor flow',role:'Experienced professional',intro:'Turn experience from the workshop or job site into a clear, reviewable guide for the trade community.',steps:[['Login','Sign in to your member workspace.','#/login'],['Create knowledge article','Start a new field note with a title, category, and step-by-step details.','#/create'],['Upload images or diagrams','Add a supporting photo or diagram to make a step easier to follow.','#/create'],['Publish tutorial','Submit the guide for moderator review.','#/create'],['Respond to user comments','Return to your desk to follow contributions and discussions.','#/dashboard']],cta:'Write a field note',route:'#/create'},{stamp:'PATH 03 · MODERATION',title:'Admin flow',role:'Platform moderator',intro:'Keep shared knowledge organized, useful, and safe while monitoring participation across the platform.',steps:[['Monitor platform content','Review recent guides and activity from the moderation workspace.','#/admin'],['Manage users','Review member accounts and contributor access.','#/admin'],['Approve or remove posts','Publish suitable submissions or remove incorrect and inappropriate content.','#/admin'],['Generate reports','Download the platform usage report for review.','#/admin']],cta:'Open admin panel',route:'#/admin'}];app.innerHTML=`<section class="page flow-page"><div class="flow-intro-strip"><span class="flow-mark" aria-hidden="true">↗</span><span><small>FIELD JOURNAL · HOW CRAFTLINE WORKS</small><b>Three paths through the Craftline community</b></span><span class="flow-stamp">USER FLOW</span></div><div class="flow-grid">${flows.map((flow,index)=>`<article class="flow-card" style="--flow-index:${index}"><div class="flow-card-top"><span class="eyebrow">${flow.stamp}</span><span class="flow-card-index">0${index+1}</span></div><h2>${flow.title}</h2><p class="flow-role">${flow.role}</p><p class="flow-intro">${flow.intro}</p><ol class="field-flow-list">${flow.steps.map(([label,copy,href],step)=>`<li><a href="${href}"><span class="flow-node">${String(step+1).padStart(2,'0')}</span><span class="flow-step-copy"><b>${label}</b><small>${copy}</small></span><span class="flow-arrow" aria-hidden="true">↗</span></a></li>`).join('')}</ol><div class="flow-card-foot"><span>${String(flow.steps.length).padStart(2,'0')} CHECKPOINTS</span><a class="btn btn-dark" href="${flow.route}">${flow.cta} <span aria-hidden="true">→</span></a></div></article>`).join('')}</div><section class="assumptions-section" aria-labelledby="assumptions-title"><div class="assumptions-heading"><span class="eyebrow">FIELD JOURNAL · PROJECT NOTES</span><h2 id="assumptions-title">Assumptions &amp; Constraints</h2><p>Conditions and limits shaping Craftline’s first release.</p></div><div class="assumptions-grid"><article class="assumption-card"><span class="assumption-index">01 · EXPECTED CONDITIONS</span><h3>Assumptions</h3><ul><li>Skilled professionals are willing to share knowledge.</li><li>Students actively use the platform for learning.</li><li>Content quality improves through community feedback.</li></ul></article><article class="assumption-card constraint-card"><span class="assumption-index">02 · PRACTICAL LIMITS</span><h3>Constraints</h3><ul><li>Quality of information depends on contributors.</li><li>Content moderation may require manual review.</li><li>Platform growth depends on community participation.</li></ul></article></div></section><section class="deployment-deliverable" aria-labelledby="deployment-deliverable-title"><div class="deployment-deliverable-copy"><span class="deployment-deliverable-kicker">REMAINING DELIVERABLE · 01</span><h2 id="deployment-deliverable-title">Live deployed application link</h2><p>A public hosting URL will be added here after deployment is configured.</p></div><span class="deployment-status" role="status"><i aria-hidden="true"></i> Hosting setup pending</span></section><div class="flow-safety"><span class="flow-safety-mark">FIELD RULE</span><p>Guides support practical learning; always follow local codes, workplace safety procedures, and manufacturer instructions.</p><a href="#/feed">Back to the journal ↗</a></div></section>`}
function renderLogin(){app.innerHTML=`<section class="page">${head('MEMBER ENTRY',state.authMode==='login'?'Sign in to Craftline':'Join the field journal','Secure member accounts protect contributions and community discussion.')}<div class="split"><form class="form-card" id="authForm"><div class="filters"><button type="button" class="chip ${state.authMode==='login'?'active':''}" data-mode="login">Sign in</button><button type="button" class="chip ${state.authMode==='register'?'active':''}" data-mode="register">Create account</button></div>${state.authMode==='register'?`<div class="field"><label for="memberName">Name</label><input id="memberName" name="name" required minlength="2" maxlength="80" placeholder="e.g. Asha Kumar"></div>`:''}<div class="field"><label for="memberEmail">Email address</label><input id="memberEmail" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div>${state.authMode==='register'?`<div class="form-row"><div class="field"><label for="memberTrade">Trade / specialization</label><select id="memberTrade" name="trade">${state.categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}<option>Trade learner</option></select></div><div class="field"><label for="memberExperience">Experience level</label><select id="memberExperience" name="experience"><option>Student / apprentice</option><option>1–5 years</option><option>6–10 years</option><option>10+ years</option><option>Instructor</option></select></div></div>`:''}<div class="field"><label for="memberPassword">Password</label><input id="memberPassword" name="password" type="password" required minlength="${state.authMode==='register'?12:1}" autocomplete="${state.authMode==='register'?'new-password':'current-password'}" placeholder="${state.authMode==='register'?'At least 12 characters':'Your password'}">${state.authMode==='register'?'<small>Use at least 12 characters. Passwords are protected by the server.</small>':''}</div>${state.authMode==='register'?'<label class="checkbox"><input name="terms" type="checkbox" required><span>I will share safe, respectful, and practical knowledge.</span></label>':''}<button class="btn btn-primary" style="margin-top:18px">${state.authMode==='login'?'Sign in':'Create account'}</button><p class="hint" style="margin-top:14px">Moderator? Sign in with the administrator credentials configured by the site owner.</p></form><aside class="side"><div class="side-card"><div class="eyebrow">WHY CRAFTLINE</div><h3>Good work deserves good notes.</h3><p class="hint">Browse trade categories, learn from real work, and add your own experience to a growing practical knowledge base.</p></div><div class="side-card"><h3>Member tools</h3><p class="hint">Publish step-by-step guides, include an image, join discussions, and bookmark reliable notes.</p></div></aside></div></section>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.authMode=b.dataset.mode;renderLogin()});document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const payload={email:f.get('email'),password:f.get('password')};if(state.authMode==='register')Object.assign(payload,{name:f.get('name'),trade:f.get('trade'),experience:f.get('experience')});try{const result=await api(state.authMode==='login'?'/login':'/register',{method:'POST',body:JSON.stringify(payload)});state.user=result.user;await refresh();toast(state.authMode==='login'?'Signed in securely':'Your account is ready');go('#/dashboard')}catch(err){toast(err.message)}}}
function renderCreateBase(){if(!state.user){app.innerHTML=`<section class="page">${head('CONTRIBUTOR WORKBENCH','Create a tutorial','Sign in to publish a guide for the community.')}<div class="card gate"><a class="btn btn-primary" href="#/login">Sign in to write →</a></div></section>`;return}app.innerHTML=`<section class="page">${head('CONTRIBUTOR WORKBENCH','Create a tutorial','Write clear steps, add a helpful image, and choose its trade category.')}<div class="split"><form class="form-card" id="guideForm"><div class="field"><label for="guideTitle">Tutorial title</label><input id="guideTitle" name="title" required minlength="8" maxlength="100" placeholder="Describe the task or problem clearly"></div><div class="form-row"><div class="field"><label for="guideTrade">Trade category</label><select id="guideTrade" name="trade">${state.categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="guideKind">Guide type</label><select id="guideKind" name="kind"><option>Field guide</option><option>Troubleshooting</option><option>Workshop note</option><option>Learning note</option><option>Maintenance</option></select></div></div><div class="field"><label for="guideSummary">Short summary</label><textarea id="guideSummary" name="summary" required minlength="25" maxlength="260" style="min-height:78px" placeholder="What will someone learn or solve?"></textarea></div><div class="field"><label for="guideBody">Step-by-step guide</label><textarea id="guideBody" name="body" required minlength="80" maxlength="12000" placeholder="Explain preparation, tools, steps, checks, and safety considerations…"></textarea><small>Use short sections and practical details. Never omit safety precautions.</small></div><div class="field"><label for="guideImage">Add a photo or diagram (optional)</label><input id="guideImage" name="image" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG, or WebP under 1.2 MB.</small><div id="imagePreview"></div></div><label class="checkbox"><input type="checkbox" name="safety" required><span>I have included relevant safety guidance and readers must follow local regulations and manufacturer instructions.</span></label><div style="display:flex;gap:8px;margin-top:18px"><button class="btn btn-primary">Submit guide for review</button><a class="btn" href="#/feed">Cancel</a></div></form><aside class="side"><div class="side-card"><div class="eyebrow">BEFORE YOU PUBLISH</div><h3>Make it useful in the field.</h3><p class="hint">Name the task clearly. List tools and materials. Explain the sequence. Include checks, common mistakes, and safety guidance.</p></div><div class="side-card"><h3>Review process</h3><p class="hint">New contributions enter a moderator review queue. Approved guides appear in the journal and trade category.</p></div></aside></div></section>`;let image='';const input=document.getElementById('guideImage');input.onchange=()=>{const f=input.files[0];if(!f)return;if(f.size>900000){input.value='';toast('Select an image under 900 KB');return}const reader=new FileReader();reader.onload=()=>{image=reader.result;document.getElementById('imagePreview').innerHTML=`<img class="detail-image" src="${image}" alt="Selected guide image preview">`};reader.readAsDataURL(f)};document.getElementById('guideForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={title:f.get('title').trim(),trade:f.get('trade'),kind:f.get('kind'),summary:f.get('summary').trim(),body:f.get('body').trim(),image,safety:f.get('safety')==='on'};try{await api('/posts',{method:'POST',body:JSON.stringify(payload)});toast('Tutorial submitted for review');await refresh();go('#/dashboard')}catch(err){toast(err.message)}}}
function videoEmbedUrl(value){if(!value.trim())return '';let u;try{u=new URL(value)}catch{return ''}if(!['https:','http:'].includes(u.protocol))return '';let id='',host=u.hostname.toLowerCase();if(['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtu.be'].includes(host)){id=host.endsWith('youtu.be')?u.pathname.split('/').filter(Boolean)[0]||'':u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]{11})/)?.[1]||'';return /^[\w-]{11}$/.test(id)?`https://www.youtube-nocookie.com/embed/${id}`:''}if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(host)){id=u.pathname.split('/').filter(Boolean).at(-1)||'';return /^\d{5,12}$/.test(id)?`https://player.vimeo.com/video/${id}`:''}return ''}
function renderCreate(){renderCreateBase();const form=document.getElementById('guideForm');if(!form)return;const videoAnchor=form.querySelector('.form-row');videoAnchor?.insertAdjacentHTML('afterend',`<div class="field"><label for="guideVideo">Tutorial video (optional)</label><input id="guideVideo" type="url" maxlength="300" placeholder="Paste a YouTube or Vimeo link"><small>Embed a short demonstration that supports your written safety steps.</small><div id="videoPreview" class="video-preview-box video-sample"><iframe src="https://www.youtube-nocookie.com/embed/vRGn9MjQnGY" title="Example copper tube flaring demonstration" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><span><b>EXAMPLE FIELD DEMONSTRATION</b><small>Copper tube flaring · Paste your link above to preview your own tutorial video.</small></span></div></div>`);const videoInput=document.getElementById('guideVideo'),preview=document.getElementById('videoPreview'),tradeSelect=document.getElementById('guideTrade'),samples={Electrical:['lNghr1RbOgc','Fluke 117 multimeter essentials'],Carpentry:['c2zWr26Fjpo','Level and install wall shelf brackets'],HVAC:['YugaWpi0IyI','HVAC filter selection and airflow basics'],Mechanics:['pWFWJEwjfyw','Serpentine belt replacement overview'],Plumbing:['vRGn9MjQnGY','Copper tube flaring tool demonstration'],Welding:['gc9fBVq9NlE','MIG welding setup and technique']};const showPreview=()=>{if(videoInput.value.trim()){const url=videoEmbedUrl(videoInput.value);preview.classList.remove('video-sample');preview.replaceChildren();if(url){const frame=document.createElement('iframe');frame.src=url;frame.title='Tutorial video preview';frame.loading='lazy';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.allowFullscreen=true;preview.append(frame)}else{const message=document.createElement('span');message.textContent='Use a valid YouTube or Vimeo video link.';preview.append(message)}return}const [id,title]=samples[tradeSelect.value]||samples.Electrical;preview.classList.add('video-sample');preview.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}" title="${tradeSelect.value} sample: ${title}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><span><b>${tradeSelect.value.toUpperCase()} FIELD DEMONSTRATION</b><small>${title} · Sample only. Paste your own link to attach a video to your guide.</small></span>`};videoInput.addEventListener('input',showPreview);tradeSelect.addEventListener('change',showPreview);showPreview();form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),videoUrl=videoEmbedUrl(videoInput?.value||'');if(videoInput?.value&&!videoUrl){toast('Paste a valid YouTube or Vimeo link');return}const payload={title:f.get('title').trim(),trade:f.get('trade'),kind:f.get('kind'),summary:f.get('summary').trim(),body:f.get('body').trim(),image:document.querySelector('#imagePreview img')?.src||'',videoUrl,safety:f.get('safety')==='on'};try{await api('/posts',{method:'POST',body:JSON.stringify(payload)});toast('Tutorial submitted for review');await refresh();go('#/dashboard')}catch(err){toast(err.message)}}}
function enhancePostVideo(){const p=state.currentPost;if(route().page!=='post'||!p?.videoUrl||document.getElementById('tutorialVideo'))return;const hero=app.querySelector('.detail-hero');if(!hero)return;const section=document.createElement('section');section.id='tutorialVideo';section.className='tutorial-video';section.innerHTML=`<div class="video-heading"><span class="eyebrow">WATCH THE FIELD DEMONSTRATION</span><span class="video-stamp">FIELD VIDEO</span></div><div class="video-frame"><iframe src="${esc(p.videoUrl)}" title="${esc(p.title)} video walkthrough" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><p>Use this demonstration alongside the written steps and safety guidance.</p>`;hero.after(section)}async function renderDashboard(){if(!state.user){app.innerHTML=`<section class="page">${head('YOUR WORKBENCH','Contributor dashboard','Sign in to manage your profile and saved references.')}<div class="card gate"><a class="btn btn-primary" href="#/login">Sign in / Create account →</a></div></section>`;return}try{const d=await api('/dashboard');const mine=d.posts,bookmarked=d.saved,likes=mine.reduce((n,p)=>n+(p.helpful||0),0);app.innerHTML=`<section class="page">${head('YOUR WORKBENCH','Contributor dashboard','Your shared knowledge, saved references, and community profile.')}<div class="profile-head"><div class="portrait-large">${initials(state.user.name)}</div><div class="profile-copy"><div class="eyebrow">${state.user.role==='admin'?'PLATFORM MODERATOR':'COMMUNITY CONTRIBUTOR'}</div><h2>${esc(state.user.name)}</h2><div class="hint">${esc(state.user.trade)} · ${esc(state.user.experience)} · Member since ${esc(state.user.joined)}</div></div><button class="btn" id="editProfile">Edit profile</button></div><div class="metrics"><div class="metric"><b>${mine.filter(p=>p.status==='published').length}</b><span>Published guides</span></div><div class="metric"><b>${likes}</b><span>Helpful votes</span></div><div class="metric"><b>${bookmarked.length}</b><span>Saved guides</span></div><div class="metric"><b>${mine.reduce((n,p)=>n+(p.views||0),0)}</b><span>Tutorial reads</span></div></div><div class="two-col"><section><div class="feed-head"><div><h2>Your contributions</h2><p>Review status and reader response.</p></div><a class="btn btn-primary" href="#/create">＋ Write</a></div><div class="feed">${mine.length?mine.map(p=>`<article class="card"><div class="post-top"><span class="tag">${esc(p.trade)} · ${esc(p.status==='pending'?'In review':p.status)}</span><span class="count">${p.views||0} reads</span></div><h3 class="post-title">${p.status==='published'?`<a href="#/post/${encodeURIComponent(p.id)}">${esc(p.title)}</a>`:esc(p.title)}</h3><p class="post-desc">${esc(p.summary)}</p></article>`).join(''):'<div class="card empty">Your first field note is ready to write.</div>'}</div></section><section><div class="feed-head"><div><h2>Saved for later</h2><p>Your bookmarked workshop references.</p></div></div><div class="feed">${bookmarked.length?bookmarked.map(postCard).join(''):'<div class="card empty">Save guides from the journal to keep them here.</div>'}</div></section></div></section>`;document.getElementById('editProfile').onclick=()=>{const btn=document.getElementById('editProfile');btn.textContent='Editing';const copy=document.querySelector('.profile-copy');copy.innerHTML=`<div class="form-row"><div class="field"><label>Name</label><input id="editName" maxlength="80" value="${esc(state.user.name)}"></div><div class="field"><label>Trade</label><select id="editTrade">${state.categories.map(c=>`<option ${state.user.trade===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}<option ${state.user.trade==='Trade learner'?'selected':''}>Trade learner</option></select></div></div><label class="hint">Experience: ${esc(state.user.experience)}</label> <button class="btn btn-primary btn-sm" id="saveProfile">Save profile</button>`;document.getElementById('saveProfile').onclick=async()=>{try{const r=await api('/me',{method:'PATCH',body:JSON.stringify({name:document.getElementById('editName').value,trade:document.getElementById('editTrade').value,experience:state.user.experience})});state.user=r.user;syncHeader();toast('Profile updated');renderDashboard()}catch(e){toast(e.message)}}};bindCards()}catch(e){app.innerHTML=`<div class="card empty">${esc(e.message)}</div>`}}
async function downloadUsageReport(){try{const response=await fetch('/api/admin/report',{credentials:'same-origin'});if(!response.ok)throw new Error('Could not download the report. Sign in as a moderator and try again.');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='craftline-usage-report.csv';document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Usage report downloaded')}catch(error){toast(error.message)}}
async function renderAdmin(){if(!state.user||state.user.role!=='admin'){app.innerHTML=`<section class="page">${head('RESTRICTED AREA','Admin panel','Only authorized moderators can manage this platform.')}<div class="card gate"><a class="btn btn-primary" href="#/login">Sign in with moderator credentials →</a></div></section>`;return}try{const d=await api('/admin'),t=d.totals,contributionRate=t.users?Math.round(t.contributors/t.users*100):0;app.innerHTML=`<section class="page">${head('PLATFORM CONTROL ROOM','Admin panel','Review submissions, manage accounts and categories, and monitor usage.')}<div class="metrics"><div class="metric"><b>${t.published}</b><span>Knowledge articles published</span></div><div class="metric"><b>${t.users}</b><span>Registered users</span></div><div class="metric"><b>${t.comments+t.ratings}</b><span>User engagement · comments + ratings</span></div><div class="metric"><b>${t.views}</b><span>Tutorial views</span></div><div class="metric"><b>${contributionRate}%</b><span>Community contribution rate<small>${t.contributors} of ${t.users} accounts published a guide</small></span></div></div><div class="two-col"><section class="form-card"><div class="feed-head"><div><h2>Review queue</h2><p>${d.pending.length} guide${d.pending.length===1?'':'s'} waiting</p></div></div>${d.pending.length?d.pending.map(p=>`<div class="admin-row"><div><b>${esc(p.title)}</b><small>${esc(p.trade)} · ${esc(p.author)} · ${esc(p.date)}</small><small>${esc(p.summary)}</small></div><div class="admin-actions"><button class="btn btn-primary btn-sm" data-approve="${esc(p.id)}">Approve</button><button class="btn btn-sm" data-reject="${esc(p.id)}">Remove</button></div></div>`).join(''):'<div class="empty">The review queue is clear.</div>'}</section><section class="form-card"><div class="feed-head"><div><h2>Usage report</h2><p>Activity stored by the platform</p></div><button class="btn btn-sm" id="downloadReport">Download CSV</button></div><div class="admin-row"><span>Views</span><b>${t.views}</b></div><div class="admin-row"><span>Comments</span><b>${t.comments}</b></div><div class="admin-row"><span>Ratings</span><b>${t.ratings}</b></div><div class="admin-row"><span>Helpful votes</span><b>${t.helpful}</b></div><div class="admin-row"><span>Bookmarks</span><b>${t.bookmarks}</b></div></section></div><section class="form-card" style="margin-top:15px"><div class="feed-head"><div><h2>Manage categories</h2><p>Add a category or remove one without any published submissions.</p></div></div><form id="categoryForm" style="display:flex;gap:8px;max-width:560px;margin-bottom:12px"><input name="name" minlength="2" maxlength="40" required placeholder="New trade category" style="flex:1;min-width:0;border:1px solid var(--line);border-radius:3px;padding:10px;background:#fbfaf6"><input name="description" maxlength="200" placeholder="Short description (optional)" style="flex:2;min-width:0;border:1px solid var(--line);border-radius:3px;padding:10px;background:#fbfaf6"><button class="btn btn-primary btn-sm">Add</button></form><div class="filters">${d.categories.map(c=>`<span class="chip">${esc(c.name)} <button data-category-delete="${esc(c.name)}" aria-label="Delete ${esc(c.name)}" style="border:0;background:none;color:var(--orange)" ${state.posts.some(p=>p.trade===c.name)?'disabled title="Category contains content"':''}>×</button></span>`).join('')}</div></section><section class="form-card" style="margin-top:15px"><div class="feed-head"><div><h2>Manage contributors</h2><p>Pause or restore member access.</p></div></div>${d.users.map(u=>`<div class="admin-row"><span><b>${esc(u.name)}</b><small>${esc(u.email)} · ${esc(u.trade)} · ${esc(u.experience)}</small></span>${u.role==='admin'?'<span class="tag">Moderator</span>':`<button class="btn btn-sm" data-user="${esc(u.id)}" data-suspended="${u.suspended}">${u.suspended?'Restore access':'Pause access'}</button>`}</div>`).join('')}</section></section>`;document.getElementById('downloadReport').onclick=downloadUsageReport;
 document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>moderate(b.dataset.approve,'published'));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>removePost(b.dataset.reject));document.getElementById('categoryForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/admin/categories',{method:'POST',body:JSON.stringify({name:f.get('name'),description:f.get('description')})});await refresh();toast('Trade category added');renderAdmin()}catch(err){toast(err.message)}};document.querySelectorAll('[data-category-delete]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/categories/${encodeURIComponent(b.dataset.categoryDelete)}`,{method:'DELETE'});await refresh();toast('Category removed');renderAdmin()}catch(e){toast(e.message)}});document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/users/${encodeURIComponent(b.dataset.user)}`,{method:'PATCH',body:JSON.stringify({suspended:b.dataset.suspended!=='true'})});toast(b.dataset.suspended==='true'?'Contributor restored':'Contributor paused');renderAdmin()}catch(e){toast(e.message)}})}catch(e){app.innerHTML=`<section class="page">${head('ADMIN PANEL','Could not load controls',esc(e.message))}</section>`}}
async function moderate(id,status){try{await api(`/admin/posts/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status})});await refresh();toast('Guide approved and published');renderAdmin()}catch(e){toast(e.message)}}
async function removePost(id){try{await api(`/admin/posts/${encodeURIComponent(id)}`,{method:'DELETE'});await refresh();toast('Guide removed');renderAdmin()}catch(e){toast(e.message)}}
let lastRoute='';
async function renderCommunity(view='members'){const views={comments:'Comments',ratings:'Ratings',contributors:'Members who published',members:'Registered accounts'},active=views[view]?view:'members',posts=state.posts;const tabs=Object.entries(views).map(([key,label])=>`<a class="community-tab ${active===key?'active':''}" href="#/community/${key}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('');let content='',people=[];if(active==='comments'){const discussed=posts.filter(p=>(p.commentCount||0)>0);content=discussed.length?discussed.map(p=>`<a class="community-entry community-entry-link" href="#/post/${encodeURIComponent(p.id)}"><div class="community-entry-meta"><b>${esc(p.title)}</b><span class="community-rating">▤ ${p.commentCount} ${p.commentCount===1?'comment':'comments'}</span></div><small class="community-muted">${esc(p.trade)} · ${esc(p.author)}</small><span class="community-guide-link">Read the discussion on this field note <span>Open comments ↗</span></span></a>`).join(''):'<div class="empty">No discussion has been posted yet. Open a guide to ask a question or share a field-tested clarification.</div>'}else if(active==='ratings'){const rated=posts.filter(p=>(p.ratingCount||0)>0).sort((a,b)=>(b.ratingCount||0)-(a.ratingCount||0));content=rated.length?rated.map(p=>`<a class="community-entry community-entry-link" href="#/post/${encodeURIComponent(p.id)}"><div class="community-entry-meta"><b>${esc(p.title)}</b><span class="community-rating">★ ${Number(p.ratingAverage||0).toFixed(1)} <small>(${p.ratingCount} ${p.ratingCount===1?'rating':'ratings'})</small></span></div><small class="community-muted">${esc(p.trade)} · ${esc(p.author)}</small><span class="community-guide-link">Open guide and feedback ↗</span></a>`).join(''):'<div class="empty">No guides have ratings yet. Visit a field note to leave a rating.</div>'}else{const groups=new Map();posts.forEach(p=>{const name=p.author||'Community contributor';if(!groups.has(name))groups.set(name,{name,role:p.role||p.trade,posts:[]});groups.get(name).posts.push(p)});people=[...groups.values()].sort((a,b)=>a.name.localeCompare(b.name));content=active==='members'?`<div class="community-count-card"><span class="eyebrow">COMMUNITY ACCOUNTS</span><strong>${state.kpis.users.toLocaleString()}</strong><p>Registered accounts currently counted in Craftline.</p><small>For privacy, this directory lists only members with public published guides. Private account details are not exposed.</small></div>`:'';content+=people.length?people.map(person=>`<article class="community-entry"><div class="community-person"><span class="portrait">${esc(initials(person.name))}</span><span><b>${esc(person.name)}</b><small>${esc(person.role)} · ${person.posts.length} published ${person.posts.length===1?'guide':'guides'}</small></span></div><div class="community-guide-list">${person.posts.slice(0,4).map(p=>`<a href="#/post/${encodeURIComponent(p.id)}">${esc(p.title)} <span>↗</span></a>`).join('')}</div></article>`).join(''):'<div class="empty">No public contributor profiles are available yet.</div>'}const summary=active==='comments'?`${posts.filter(p=>(p.commentCount||0)>0).length} field notes with community discussion`:active==='ratings'?'Community ratings, linked back to each guide':`${people.length} public contributor profiles with published notes`;app.innerHTML=`<section class="page community-page">${head('FIELD JOURNAL · COMMUNITY',views[active],({members:'Explore registered community accounts and public guide contributors.',comments:'Open guides with community comments to read the full discussion.',ratings:'Browse community feedback and open the guides behind each rating.',contributors:'Meet the members who have published practical trade guides.'})[active])}<nav class="community-tabs" aria-label="Community sections">${tabs}</nav><div class="community-results"><p class="community-summary">${summary}</p>${content}</div></section>`}async function render(){const {page,id,view}=route();if(location.hash!==lastRoute){app.classList.remove('route-transition');void app.offsetWidth;app.classList.add('route-transition');lastRoute=location.hash}document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.link===page||(page==='post'&&a.dataset.link==='feed')||(page==='category'&&a.dataset.link==='category')));if(page==='feed'||page==='category'||page==='community')try{await refresh()}catch(e){toast(e.message)}if(page==='feed')renderFeed();else if(page==='login')renderLogin();else if(page==='flow')renderFlow();else if(page==='post')renderPost(id);else if(page==='create')renderCreate();else if(page==='dashboard')renderDashboard();else if(page==='category')renderCategory(id||state.categories[0]?.name||'Electrical');else if(page==='admin')renderAdmin();else if(page==='community')await renderCommunity(view);else go('#/feed');window.scrollTo({top:0,behavior:'smooth'})}
async function init(){try{await refresh();if(!location.hash)history.replaceState(null,'','#/feed');render()}catch(e){app.innerHTML=`<section class="card gate"><h1 class="page-title">Craftline is starting up</h1><p>${esc(e.message)}</p><p class="hint">Run the Node.js server to connect to the secure knowledge library.</p></section>`}}
const revealObserver='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal-in');revealObserver.unobserve(entry.target)}}),{threshold:0,rootMargin:'0px 0px -12px 0px'}):null;
function enhancePageBase(){if(route().page==='feed'&&!document.getElementById('journalStats')){const values=[['Number of knowledge articles published',state.kpis.published.toString().padStart(2,'0'),'Published field notes'],['Number of registered users',state.kpis.users.toLocaleString(),'Active accounts'],['User engagement (comments, ratings)',state.kpis.engagement.toLocaleString(),`${state.kpis.comments} comments · ${state.kpis.ratings} ratings`],['Number of tutorial views',state.kpis.views.toLocaleString(),'Across all guides'],['Community contribution rate',`${state.kpis.contributionRate}%`,`${state.kpis.contributors} of ${state.kpis.users} users published`]];const strip=document.createElement('section');strip.id='journalStats';strip.className='journal-stats';strip.setAttribute('aria-label','Key performance indicators');strip.innerHTML=`<div class="journal-kpi-header"><div><span class="journal-kpi-eyebrow">FIELD JOURNAL <i></i> LIVE INDEX</span><h2>Key Performance Indicators <span>(KPIs)</span></h2><p>A quick read on knowledge shared across Craftline.</p></div><div class="journal-kpi-stamp" aria-label="Five live measures"><small>ISSUE</small><b>05</b><span>LIVE</span></div></div><div class="journal-kpi-list">${values.map(([label,value,detail])=>`<div class="journal-stat"><span class="journal-kpi-label">• ${label}</span><b>${value}</b><small>${detail}</small></div>`).join('')}</div>`;document.querySelector('.hero')?.after(strip)}if(route().page==='dashboard'&&state.user&&!document.getElementById('signOutButton')){const head=document.querySelector('.profile-head');if(head){const button=document.createElement('button');button.id='signOutButton';button.className='btn';button.textContent='Sign out';button.onclick=async()=>{try{await api('/logout',{method:'POST',body:'{}'});state.user=null;state.saved=[];state.currentPost=null;syncHeader();toast('Signed out');go('#/feed')}catch(e){toast(e.message)}};head.append(button)}}if(revealObserver)app.querySelectorAll('.card,.form-card,.side-card,.metric,.profile-head,.detail-hero').forEach(el=>{if(el.classList.contains('reveal-ready'))return;el.classList.add('reveal-ready');requestAnimationFrame(()=>revealObserver.observe(el))})}function animateStatCount(el,finalText,index){const target=Number(finalText.replace(/[^\d]/g,''));if(!Number.isFinite(target)||finalText.endsWith('%')||matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=finalText;return}const width=finalText.startsWith('0')&&!finalText.includes(',')?finalText.length:0,start=performance.now()+index*75,duration=650;const tick=now=>{if(now<start){requestAnimationFrame(tick);return}const t=Math.min(1,(now-start)/duration),eased=1-Math.pow(1-t,3),n=Math.round(target*eased);el.textContent=width?String(n).padStart(width,'0'):finalText.includes(',')?n.toLocaleString():String(n);if(t<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}function journalPanelMarkup(key){const panelTitle={notes:'Published field notes',members:'Registered community',engagement:'Community engagement',reads:'Most-read field notes',contribution:'Community contribution rate'}[key];let rows='';if(key==='notes')rows=state.posts.map(p=>`<a class="journal-panel-row" href="#/post/${encodeURIComponent(p.id)}"><span><b>${esc(p.title)}</b><small>${esc(p.trade)} · ${esc(p.kind)}</small></span><span class="journal-panel-value">${p.views||0}<small>READS</small></span></a>`).join('');else if(key==='members')rows=`<a class="journal-panel-row" href="#/community/members"><span><b>Registered user accounts</b><small>Open the community member directory →</small></span><span class="journal-panel-value">${state.kpis.users.toLocaleString()}<small>USERS</small></span></a>`;else if(key==='engagement')rows=`<a class="journal-panel-row" href="#/community/comments"><span><b>Comments</b><small>Questions and shared field experience · View discussion →</small></span><span class="journal-panel-value">${state.kpis.comments.toLocaleString()}</span></a><a class="journal-panel-row" href="#/community/ratings"><span><b>Ratings</b><small>Community feedback on published guides · View ratings →</small></span><span class="journal-panel-value">${state.kpis.ratings.toLocaleString()}</span></a>`;else if(key==='contribution')rows=`<a class="journal-panel-row" href="#/community/contributors"><span><b>Members who published</b><small>Accounts with at least one published guide · View contributors →</small></span><span class="journal-panel-value">${state.kpis.contributors.toLocaleString()}</span></a><a class="journal-panel-row" href="#/community/members"><span><b>Registered accounts</b><small>Contribution rate denominator · View community →</small></span><span class="journal-panel-value">${state.kpis.users.toLocaleString()}</span></a>`;else rows=[...state.posts].sort((a,b)=>(b.views||0)-(a.views||0)).slice(0,5).map((p,i)=>`<a class="journal-panel-row" href="#/post/${encodeURIComponent(p.id)}"><span><b><i class="journal-rank">0${i+1}</i>${esc(p.title)}</b><small>${esc(p.trade)} · ${esc(p.author)}</small></span><span class="journal-panel-value">${(p.views||0).toLocaleString()}<small>READS</small></span></a>`).join('');return `<div class="journal-panel-head"><div><span class="eyebrow">FIELD JOURNAL INDEX</span><h3>${panelTitle}</h3></div><span class="journal-panel-close">Click the active counter to close</span></div><div class="journal-panel-list">${rows||'<div class="empty">Nothing to show yet.</div>'}</div>`}function enhancePage(){enhancePageBase();const strip=document.getElementById('journalStats');if(!strip||strip.dataset.interactive)return;strip.dataset.interactive='true';const keys=['notes','members','engagement','reads','contribution'];const labels=['published field notes','registered users','community engagement','tutorial views','community contribution rate'];strip.querySelectorAll('.journal-stat').forEach((old,index)=>{const button=document.createElement('button');button.type='button';button.className='journal-stat';button.style.setProperty('--stagger',index);button.dataset.journalStat=keys[index];const label=old.querySelector('.journal-kpi-label')?.textContent||'';const value=old.querySelector('b')?.textContent||'0';const detail=old.querySelector('small')?.textContent||'';button.innerHTML=`<span class="journal-kpi-check" aria-hidden="true">${String(index+1).toString().padStart(2,String.fromCharCode(48))}</span><span class="journal-kpi-copy"><b>${label}</b><small>${detail}</small></span><strong class="journal-stat-number">${value}</strong><span class="journal-kpi-open" aria-hidden="true">↗</span>`;button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','journalStatPanel');button.setAttribute('aria-label',`Open ${labels[index]}`);old.replaceWith(button);animateStatCount(button.querySelector('.journal-stat-number'),value,index)});strip.querySelectorAll('[data-journal-stat]').forEach(button=>button.addEventListener('click',()=>{const wasOpen=button.getAttribute('aria-expanded')==='true';strip.querySelectorAll('[data-journal-stat]').forEach(item=>{item.setAttribute('aria-expanded','false');item.classList.remove('active')});strip.querySelector('#journalStatPanel')?.remove();if(wasOpen)return;button.setAttribute('aria-expanded','true');button.classList.add('active');const panel=document.createElement('section');panel.id='journalStatPanel';panel.className='journal-stat-panel';panel.innerHTML=journalPanelMarkup(button.dataset.journalStat);strip.append(panel);requestAnimationFrame(()=>panel.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth",block:"nearest"}))}))}function enhanceWorkspace(){const form=document.getElementById('guideForm');if(form&&!document.getElementById('writeProgress')){const meter=document.createElement('div');meter.id='writeProgress';meter.className='write-progress';meter.innerHTML='<span>FIELD NOTE CHECKLIST</span><div class="write-progress-track" role="progressbar" aria-label="Guide completeness" aria-valuemin="0" aria-valuemax="4" aria-valuenow="0"><div class="write-progress-fill"></div></div><strong>0/4</strong>';form.prepend(meter);const update=()=>{const done=[form.elements.title.value.trim().length>=8,form.elements.summary.value.trim().length>=25,form.elements.body.value.trim().length>=80,form.elements.safety.checked].filter(Boolean).length;meter.querySelector('.write-progress-fill').style.width=`${done*25}%`;meter.querySelector('strong').textContent=`${done}/4`;meter.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',done)};form.addEventListener('input',update);form.addEventListener('change',update);update()}if(route().page==='category'&&!document.getElementById('tradePulse')){const page=app.querySelector('.page'),title=page?.querySelector('.page-title'),name=title?.textContent;if(page&&name){const total=state.posts.filter(p=>p.trade.toLowerCase()===name.toLowerCase()).length;const pulse=document.createElement('div');pulse.id='tradePulse';pulse.className='trade-pulse';pulse.innerHTML=`<span class="trade-pulse-mark">✳</span><span><small>TRADE FIELD INDEX</small><b>${esc(name)} reference shelf</b></span><span class="trade-pulse-total"><strong>${String(total).padStart(2,'0')}</strong><small>FIELD NOTES</small></span>`;page.querySelector('.page-head')?.after(pulse)}}}
function enhancePostRating(){const p=state.currentPost;if(route().page!=='post'||!p||document.getElementById('guideRatingForm'))return;const hero=app.querySelector('.detail-hero');if(!hero)return;const box=document.createElement('section');box.className='guide-rating-box';box.innerHTML=`<div class="rating-copy"><span class="eyebrow">COMMUNITY RATING · FIELD REVIEW</span><div class="guide-rating-summary">${p.ratingCount?`★ ${Number(p.ratingAverage).toFixed(1)} out of 5 · ${p.ratingCount} ${p.ratingCount===1?'rating':'ratings'}`:'Not rated yet · Be the first to rate this guide'}</div></div><form id="guideRatingForm"><input type="hidden" name="score" value=""><div class="rating-prompt">Your field rating <span>Tap a star to mark this guide</span></div><div class="rating-dial" role="group" aria-label="Rate this guide from one to five stars">${[1,2,3,4,5].map(n=>`<button class="rating-star" type="button" data-star="${n}" aria-label="${n} ${n===1?'star':'stars'}: ${['Not useful','Needs more detail','Useful','Very useful','Excellent'][n-1]}" aria-pressed="false">★</button>`).join('')}</div><div class="rating-selection" aria-live="polite">Choose a rating</div><button class="btn btn-primary btn-sm rating-submit" disabled>Pin my rating <span>↗</span></button></form></section>`;hero.after(box);let selected=0,hovered=0;const labels=['','Not useful yet','Needs more detail','Useful in the field','Very useful','Excellent field note'];const stars=[...box.querySelectorAll('[data-star]')],scoreInput=box.querySelector('[name="score"]'),feedback=box.querySelector('.rating-selection'),submit=box.querySelector('.rating-submit');const paint=()=>{const active=hovered||selected;stars.forEach(star=>{const lit=Number(star.dataset.star)<=active;star.classList.toggle('lit',lit);star.setAttribute('aria-pressed',String(Number(star.dataset.star)===selected))});feedback.textContent=active?`${active} / 5 · ${labels[active]}`:'Choose a rating'};stars.forEach(star=>{star.addEventListener('mouseenter',()=>{hovered=Number(star.dataset.star);paint()});star.addEventListener('focus',()=>{hovered=Number(star.dataset.star);paint()});star.addEventListener('blur',()=>{hovered=0;paint()});star.addEventListener('click',()=>{selected=Number(star.dataset.star);scoreInput.value=String(selected);hovered=0;submit.disabled=false;paint()})});box.querySelector('.rating-dial').addEventListener('mouseleave',()=>{hovered=0;paint()});box.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!selected){toast('Choose a star rating first');return}try{const result=await api(`/posts/${encodeURIComponent(p.id)}/rating`,{method:'POST',body:JSON.stringify({score:selected})});p.ratingAverage=result.average;p.ratingCount=result.count;const cached=state.posts.find(item=>item.id===p.id);if(cached){cached.ratingAverage=result.average;cached.ratingCount=result.count}toast('Your field rating was pinned');renderPostWithoutFetch(p)}catch(error){toast(error.message);if(!state.user)go('#/login')}}}
function enhanceTradeChoiceBoxes(){const definitions={guideTrade:{title:'Choose your trade shelf',sub:'FIELD SPECIALTIES',items:{Carpentry:['⌁','WOOD & FINISH','Layout, joinery, installation'],Electrical:['ϟ','POWER & CONTROLS','Wiring, circuits, safe diagnostics'],HVAC:['⌘','CLIMATE SYSTEMS','Airflow, heating, cooling'],Mechanics:['⚙','MACHINERY','Engines, equipment, maintenance'],Plumbing:['⌇','WATER SYSTEMS','Pipes, fixtures, repairs'],Welding:['✳','METALWORK','Joining, fabrication, shop practice']}},memberTrade:{title:'Choose your trade',sub:'YOUR SPECIALTY',items:{Carpentry:['⌁','WOOD & FINISH','Joinery, installation, and finish work'],Electrical:['ϟ','POWER & CONTROLS','Wiring, circuits, and diagnostics'],HVAC:['⌘','CLIMATE SYSTEMS','Heating, ventilation, and cooling'],Mechanics:['⚙','MACHINERY','Engines, equipment, and maintenance'],Plumbing:['⌇','WATER SYSTEMS','Pipes, fixtures, and repairs'],Welding:['✳','METALWORK','Fabrication and joining'], 'Trade learner':['✎','EXPLORING TRADES','Learning across practical specialties']}},memberExperience:{title:'Choose your experience level',sub:'YOUR BACKGROUND',items:{'Student / apprentice':['✦','LEARNING','Building practical trade skills'],'1–5 years':['01','EARLY CAREER','Developing hands-on experience'],'6–10 years':['06','EXPERIENCED','Growing independent practice'],'10+ years':['10','SEASONED','Deep field knowledge'],Instructor:['▤','EDUCATOR','Teaching and mentoring others']}},guideKind:{title:'Choose a guide format',sub:'FIELD NOTE FORMAT',items:{'Field guide':['▤','PRACTICAL METHOD','A clear sequence for doing a task'],'Troubleshooting':['⌕','FAULT FINDING','Checks to trace a problem safely'],'Workshop note':['⚒','SHOP PRACTICE','A setup, technique, or bench-side tip'],'Learning note':['✎','SKILL BUILDING','A lesson for students and apprentices'],'Maintenance':['⟳','CARE & SERVICE','Inspection and preventive upkeep']}}};for(const [id,definition] of Object.entries(definitions)){const select=document.getElementById(id);if(!select||select.closest('.craft-choice'))continue;const field=select.closest('.field');if(!field)continue;const label=field.querySelector('label[for="'+id+'"]');const shell=document.createElement('div');shell.className='craft-choice craft-choice-'+(id==='guideTrade'||id==='memberTrade'?'trade':id==='memberExperience'?'experience':'format');shell.dataset.choice=id;select.parentNode.insertBefore(shell,select);shell.append(select);select.classList.add('craft-choice-source');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const trigger=document.createElement('button');trigger.type='button';trigger.className='craft-choice-trigger';trigger.id=id+'Picker';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',id+'Options');trigger.setAttribute('aria-label',(label?.textContent||'Choose an option').trim());if(label)label.htmlFor=trigger.id;const panel=document.createElement('div');panel.className='craft-choice-panel';panel.id=id+'Options';panel.setAttribute('role','listbox');panel.setAttribute('aria-label',definition.title);panel.hidden=true;const title=document.createElement('div');title.className='craft-choice-panel-head';title.innerHTML='<small>'+definition.sub+' · '+String(select.options.length).padStart(2,'0')+' OPTIONS</small><b>'+definition.title+'</b>';panel.append(title);const list=document.createElement('div');list.className='craft-choice-options';for(const [optionIndex,option] of [...select.options].entries()){const metadata=definition.items[option.value]||['✳','FIELD NOTE','A practical guide from the trade community'];const choice=document.createElement('button');choice.type='button';choice.className='craft-choice-option';choice.setAttribute('role','option');choice.dataset.value=option.value;choice.style.setProperty('--choice-i',optionIndex);choice.setAttribute('aria-selected',String(option.selected));choice.innerHTML='<span class="craft-choice-glyph" aria-hidden="true">'+metadata[0]+'</span><span class="craft-choice-copy"><b>'+option.textContent+'</b><small><i>'+metadata[1]+'</i>'+metadata[2]+'</small></span><span class="craft-choice-check" aria-hidden="true">✓</span>';list.append(choice);choice.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));close(false);trigger.focus()})}panel.append(list);shell.append(trigger,panel);const selectedMeta=()=>definition.items[select.value]||['✳','FIELD NOTE','A practical guide from the trade community'];const sync=()=>{const meta=selectedMeta();trigger.innerHTML='<span class="craft-choice-selected"><i class="craft-choice-glyph" aria-hidden="true">'+meta[0]+'</i><span><small>'+meta[1]+'</small><b>'+select.options[select.selectedIndex]?.textContent+'</b></span></span><span class="craft-choice-chevron" aria-hidden="true">⌄</span>';panel.querySelectorAll('[role="option"]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.value===select.value)))};const close=focus=>{panel.hidden=true;trigger.setAttribute('aria-expanded','false');shell.classList.remove('is-open');if(focus)trigger.focus()};const open=focus=>{document.querySelectorAll('.craft-choice.is-open').forEach(other=>{if(other!==shell){other.querySelector('.craft-choice-panel').hidden=true;other.querySelector('.craft-choice-trigger').setAttribute('aria-expanded','false');other.classList.remove('is-open')}});panel.hidden=false;trigger.setAttribute('aria-expanded','true');shell.classList.add('is-open');if(focus)(panel.querySelector('[aria-selected="true"]')||panel.querySelector('[role="option"]'))?.focus()};sync();select.addEventListener('change',sync);trigger.addEventListener('click',()=>panel.hidden?open(false):close(false));trigger.addEventListener('keydown',event=>{if(['ArrowDown','ArrowUp','Enter',' '].includes(event.key)){event.preventDefault();open(true)}else if(event.key==='Escape')close(false)});panel.addEventListener('keydown',event=>{const options=[...panel.querySelectorAll('[role="option"]')],index=options.indexOf(document.activeElement);let next=index;if(event.key==='ArrowDown')next=(index+1)%options.length;else if(event.key==='ArrowUp')next=(index-1+options.length)%options.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=options.length-1;else if(event.key==='Escape'){event.preventDefault();close(true);return}else return;event.preventDefault();options[next]?.focus()})}if(!window.__craftChoiceOutside){window.__craftChoiceOutside=true;document.addEventListener('click',event=>{if(!event.target.closest('.craft-choice'))document.querySelectorAll('.craft-choice.is-open').forEach(shell=>{shell.querySelector('.craft-choice-panel').hidden=true;shell.querySelector('.craft-choice-trigger').setAttribute('aria-expanded','false');shell.classList.remove('is-open')})})}}
new MutationObserver(()=>{enhancePage();enhanceWorkspace();enhanceTradeChoiceBoxes();enhancePostVideo();enhancePostRating()}).observe(app,{childList:true,subtree:true});
function updateReadingProgress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.topbar').style.setProperty('--read-progress',max>0?`${Math.min(1,scrollY/max)}`:'0')}
addEventListener('scroll',updateReadingProgress,{passive:true});
